INSERT INTO `creature_text` (`entry`,`groupid`,`id`,`text`,`type`,`language`,`probability`,`emote`,`duration`,`sound`,`comment`) VALUES
(43778,0,0,'Foe Reaper 5000 on-line.  All systems nominal.',14,0,100.0,0,0,22137,'Foe Reaper 5000'),
(43778,1,0,'|TInterface\\Icons\\ability_whirlwind.blp:20|t Foe Reaper 5000 begins to activate |cFFFF0000|Hspell:88481|h[Overdrive]|h|r!',41,0,100.0,0,0,0,'Foe Reaper 5000'),
(43778,2,0,'Overdrive engine activated.',14,0,100.0,0,0,22142,'Foe Reaper 5000'),
(43778,3,0,'Acquiring target...',14,0,100.0,0,0,22140,'Foe Reaper 5000 to Player'),
(43778,4,0,'Target acquired.  Harvesting servos engaged.',14,0,100.0,0,0,22141,'Foe Reaper 5000'),
(43778,5,0,'Safety restrictions off-line.  Catastrophic system failure imminent.',14,0,100.0,0,0,22143,'Foe Reaper 5000'),
(43778,6,0,'|TInterfaceIconsspell_fire_totemofwrath.blp:20|t Foe Reaper 5000 |cFFFF0000|Hspell:88522|h[Safety Restrictions are Off-line]|h|r!',41,0,100.0,0,0,0,'Foe Reaper 5000'),
(43778,7,0,'Target destroyed.',14,0,100.0,0,0,22139,'Feindschnitter 5000 to Player'),
(43778,8,0,'Overheat threshold exceeded.  System failure.  Wheat clog in port two.  Shutting down.',14,0,100.0,0,0,22138,'Foe Reaper 5000'),
(47162,0,0,'Glubtok show you da power of de arcane!',14,0,100.0,0,0,21151,'Glubtok to Player'),
(47162,1,0,'Fists of flame!',14,0,100.0,0,0,21153,'Glubtok'),
(47162,2,0,'Fists of frost!',14,0,100.0,0,0,21156,'Glubtok'),
(47162,3,0,'Glubtok ready?',14,0,100.0,1,0,21154,'Glubtok'),
(47162,3,1,'\'Sploded dat one!',14,0,0.0,0,0,21155,'VO_DM_GlubtokHead2_Kill01'),
(47162,4,0,'Let\'s do it!',14,0,100.0,15,0,21157,'Glubtok'),
(47162,5,0,'ARCANE POWER!!!',14,0,100.0,15,0,21146,'Glubtok'),
(47162,6,0,'|TInterface\\Icons\\spell_holy_innerfire.blp:20|t Glubtok creates a moving |cFFFF0000|Hspell:91398|h[Fire Wall]|h|r!',41,0,100.0,0,0,0,'Glubtok'),
(47162,7,0,'TOO...MUCH...POWER!!!',14,0,100.0,15,0,21145,'Glubtok'),
(47297,0,1,'No...NO!',14,0,100.0,0,0,20854,'Lumbering Oaf to Helix Gearbreaker'),
(47297,1,2,'OAF SMASH!!',14,0,100.0,0,0,0,'Lumbering Oaf to Helix Gearbreaker'),
(47626,0,0,'Ah, fresh meat!',14,0,100.0,0,0,19882,'Admiral Ripsnarl - Aggro'),
(47626,1,0,'Do you feel that chill running up your spine?',14,0,100.0,0,0,19877,'Admiral Ripsnarl - Fog 1'),
(47626,2,0,'The fog is rolling in...',14,0,100.0,0,0,0,'Admiral Ripsnarl - Fog 2'),
(47626,3,0,'Your blood only increases my hunger!',14,0,100.0,0,0,19876,'Admiral Ripsnarl - Slay'),
(47626,4,0,'I can smell your fear...',14,0,100.0,0,0,19879,'Admiral Ripsnarl - Go for the Throat 1'),
(47626,4,1,'I will rip your heart from your chest!',14,0,100.0,0,0,19880,'Admiral Ripsnarl - Go for the Throat 2'),
(47626,5,0,'Multiple vapors appear from the fog!  Kill Admiral Ripsnarl before you are overwhelmed!',41,0,100.0,0,0,19878,'Admiral Ripsnarl - Announce Vapor'),
(47626,6,0,'You will...NOT find her...until it is too late...',14,0,100.0,0,0,19875,'Admiral Ripsnarl - Death'),
(48280,0,0,'They\'re alive...',12,0,100.0,0,0,0,'Goblin Craftsman to Player'),
(48280,1,0,'THEY\'RE ALIVE!!!',14,0,100.0,0,0,0,'Goblin Craftsman to Player'),
(48280,2,0,'NOOOOOOO!!!',14,0,100.0,0,0,0,'Goblin Craftsman to Player'),
(48439,0,0,'RUN!',14,0,100.0,0,0,0,'Goblin Engineer to Player'),
(49139,0,0,'Blowin\' em\' to bits, boss!',12,0,100.0,0,0,0,'Helix Crew - Throw Bomb'),
(49454,0,0,'Activate the steam valves to free yourself!',41,0,100.0,0,0,0,'Vanessa\'s Trap Bunny to Player'),
(49541,0,0,'I will not share my father\'s fate!  Your tale ends here!',14,0,100.0,0,0,24599,'Vanessa van Cleef to Player'),
(49541,1,0,'The first of many.',14,0,100.0,0,0,24620,'Vanessa van Cleef'),
(49541,1,1,'If I\'m going to die, I\'m taking you all with me!',14,0,100.0,0,0,24611,'Vanessa VanCleef death 2'),
(49541,1,2,'MY FATE IS MY OWN!',14,0,100.0,0,0,24612,'Vanessa VanCleef death 3'),
(49541,2,0,'Did you really think I would come to this fight alone?',14,0,100.0,0,0,24620,'Vanessa van Cleef'),
(49541,3,0,'Fools!  This entire ship is rigged with explosives!  Enjoy your fiery deaths!',14,0,100.0,0,0,24621,'Vanessa van Cleef'),
(49541,4,0,'Vanessa has detonated charges on the ship!  Get to the ropes at the side of the boat!',41,0,100.0,0,0,0,'Vanessa van Cleef'),
(49541,5,0,'You didn\'t honestly think I would only plant ONE set of explosives, did you?',14,0,100.0,0,0,24622,'Vanessa van Cleef'),
(49541,6,0,'Vanessa is detonating more charges!  Get to the ropes at the side of the boat!',41,0,100.0,0,0,0,'Vanessa van Cleef'),
(49541,7,0,'ENOUGH!  I will not give you the pleasure!',14,0,100.0,274,0,24610,'Vanessa van Cleef'),
(49541,8,0,'If I\'m going to die, I\'m taking you all with me!',14,0,100.0,15,0,24611,'Vanessa van Cleef'),
(49541,9,0,'Vanessa pulls out a final barrel of mining powder and ignites it!  RUN!',41,0,100.0,0,0,0,'Vanessa van Cleef'),
(49541,10,0,'MY FATE IS MY OWN!',14,0,100.0,397,0,24612,'Vanessa van Cleef'),
(49671,0,0,'Poor Glubtok.  When his powers manifested, his own ogre mound was the first to burn.',12,0,100.0,1,0,24602,'Vanessa van Cleef to Steam Valve'),
(49671,1,0,'Deep within his soul, the one thing he feared most of all was...himself.',12,0,100.0,1,0,24603,'Vanessa van Cleef to Steam Valve'),
(49671,2,0,'You have entered Glubtok\'s Nightmare!',41,0,100.0,0,0,0,'Vanessa van Cleef to Steam Valve'),
(49671,3,0,'Get back to the ship!',41,0,100.0,0,0,0,'Vanessa van Cleef to Steam Valve'),
(49671,4,0,'Most rogues prefer to cloak themselves in the shadows, but not Helix.',12,0,100.0,1,0,24604,'Vanessa van Cleef to Player'),
(49671,5,0,'You never know what skitters in the darkness.',12,0,100.0,1,0,24605,'Vanessa van Cleef to Player'),
(49671,6,0,'Can you imagine the life of a machine?',12,0,100.0,1,0,24606,'Vanessa van Cleef to Player'),
(49671,7,0,'A simple spark can mean the difference between life...and death.',12,0,100.0,1,0,24607,'Vanessa van Cleef to Player'),
(49671,8,0,'You have entered the mechanical nightmare!',41,0,100.0,0,0,0,'Vanessa van Cleef to Player'),
(49671,9,0,'Ripsnarl wasn\'t always a bloodthirsty savage.  Once, he even had a family.',12,0,100.0,1,0,24608,'Vanessa van Cleef to Player'),
(49671,10,0,'He was called James Harrington.  A tragedy in three parts.',12,0,100.0,1,0,24609,'Vanessa van Cleef to Player'),
(49671,11,0,'You have entered Ripsnarl\'s nightmare!',41,0,100.0,0,0,0,'Vanessa van Cleef to Player'),
(49674,0,0,'You have entered Helix\'s nightmare!',41,0,100.0,0,0,0,'Helix Gearbreaker to Player'),
(49674,1,0,'Nightmare spiders appear in the darkness!  Kill Helix before his nightmare overwhelms you!',41,0,100.0,0,0,0,'Helix Geabreaker to Player');
