INSERT INTO `creature_text` (`entry`,`groupid`,`id`,`text`,`type`,`language`,`probability`,`emote`,`duration`,`sound`,`comment`) VALUES
(47296,0,0,'The mistress will pay me handsomely for your heads!',14,0,100.0,0,0,20849,'Helix Gearbreaker - Aggro'),
(47296,1,0,'Bombs away!',14,0,100.0,0,0,20847,'Helix Gearbreaker - Bomb'),
(47296,2,0,'Ready Oafie? Throw!',14,0,100.0,0,0,20848,'Helix Gearbreaker - Throw Helix'),
(47296,3,0,'Helix attaches a bomb to $n''s chest!',41,0,100.0,0,0,0,'Helix Gearbreaker - Announce Bomb'),
(47296,4,0,'I didn''t need him! Not when I''ve got YOU oafs!',14,0,100.0,0,0,20846,'Helix Gearbreaker - Oaf Death'),
(47296,5,0,'Only ten copper? You''re not even worth killing!',14,0,100.0,0,0,20845,'Helix Gearbreaker - Slay'),
(47296,6,0,'The scales...have...tipped...',14,0,100.0,0,0,20844,'Helix Gearbreaker - Death'),
(49429,0,0,'You hear a noise from above the cabin door!',41,0,100.0,0,0,0,'Vanessa van Cleef to Player'),
(49429,1,0,'I''ve been waiting a long time for this, you know.',12,0,100.0,1,0,24613,'Vanessa van Cleef to Player'),
(49429,2,0,'Biding my time, building my forces, studying the minds of my enemies.',12,0,100.0,1,0,24614,'Vanessa van Cleef to Player'),
(49429,3,0,'I was never very good at hand-to-hand combat, you know.  Not like my father.',12,0,100.0,1,0,24615,'Vanessa van Cleef to Player'),
(49429,4,0,'But I always excelled at poisons.',12,0,100.0,1,0,24616,'Vanessa van Cleef to Player'),
(49429,5,0,'Especially venoms that affect the mind.',12,0,100.0,1,0,24617,'Vanessa van Cleef to Player'),
(49429,6,0,'Vanessa injects you with the Nightmare Elixir!',41,0,100.0,0,0,0,'Vanessa van Cleef to Player'),
(49429,7,0,'He was called James Harrington.  A tragedy in three parts.',12,0,100.0,0,0,24609,'Vanessa VanCleef admiral 2'),
(49429,8,0,'I''ve been waiting a long time for this, you know.',12,0,100.0,0,0,24613,'Vanessa VanCleef intro 1'),
(49429,9,0,'Biding my time, building my forces, studying the minds of my enemies.',12,0,100.0,0,0,24614,'Vanessa VanCleef intro 2'),
(49429,10,0,'I was never very good at hand-to-hand combat, you know.  Not like my father.',12,0,100.0,0,0,24615,'Vanessa VanCleef intro 3'),
(49429,11,0,'But I always excelled at poisons.',12,0,100.0,0,0,24616,'Vanessa VanCleef intro 4'),
(49429,12,0,'Especially venoms that affect the mind.',12,0,100.0,0,0,24617,'Vanessa VanCleef intro 5'),
(49564,0,0,'A note falls to the floor!',41,0,100.0,0,0,0,'A Note from Vanessa to Player');
